#include "MyLayout.h"

#include <LayoutItem.h>
#include <View.h>

MyLayout::MyLayout()
	:
	BAbstractLayout()
{
}

MyLayout::~MyLayout()
{
}

BSize
MyLayout::MinSize()
{
	return BSize(100, 100);
}

BSize
MyLayout::MaxSize()
{
	return BSize(B_SIZE_UNLIMITED, B_SIZE_UNLIMITED);
}

BSize
MyLayout::PreferredSize()
{
	return BSize(400, 300);
}

BAlignment
MyLayout::InternalAlignment()
{
	return BAlignment(B_ALIGN_LEFT, B_ALIGN_TOP);
}

BLayoutItem*
MyLayout::AddView(BView* view)
{
	return AddView(-1, view);
}

BLayoutItem*
MyLayout::AddView(int32 index, BView* view)
{
	BLayoutItem* item = BAbstractLayout::AddView(index, view);
	return item;
}

bool
MyLayout::AddItem(BLayoutItem* item)
{
	return AddItem(-1, item);
}

bool
MyLayout::AddItem(int32 index, BLayoutItem* item)
{
	if (index < 0)
		fItems.AddItem(item);
	else
		fItems.AddItem(item, index);

	InvalidateLayout();
	return true;
}

void
MyLayout::InvalidateLayout(bool children)
{
	BAbstractLayout::InvalidateLayout(children);
}

void
MyLayout::DoLayout()
{
	if (!Owner())
		return;

	BRect area = Owner()->Bounds();
	int32 count = fItems.CountItems();
	if (count == 0)
		return;

	float itemHeight = area.Height() / count;

	for (int32 i = 0; i < count; i++) {
		BLayoutItem* item = (BLayoutItem*)fItems.ItemAt(i);
		BRect frame(
			area.left,
			area.top + i * itemHeight,
			area.right,
			area.top + (i + 1) * itemHeight - 1);
		item->AlignInFrame(frame);
	}
}
