void
MyApp::RefsReceived(BMessage* message)
{
	uint32 type;
	int32 count;
	message->GetInfo("refs", &type, &count);

	for (int32 i = 0; i < count; i++) {
		entry_ref ref;
		if (message->FindRef("refs", i, &ref) == B_OK) {
			BEntry entry(&ref);
			BPath path;
			entry.GetPath(&path);
			fWindow->AppendText(path.Path());
		}
	}
