	status_t status = BArchivable::Archive(archive, deep);
	if (status != B_OK)
		return status;

	archive->AddString("class", "ColorValue");
	archive->AddUInt8("red", fRed);
	archive->AddUInt8("green", fGreen);
	archive->AddUInt8("blue", fBlue);

	return B_OK;
}

