### Container.cpp
```cpp
#include "Container.h"

#include <Archivable.h>
#include <Message.h>
#include <stdio.h>

Container::Container(const char* name)
	:
	BArchivable(),
	fName(name)
{
}

Container::Container(BMessage* archive)
	:
	BArchivable(archive)
{
	archive->FindString("name", &fName);
}

Container::~Container()
{
	for (int32 i = 0; i < fChildren.CountItems(); i++)
		delete static_cast<Container*>(fChildren.ItemAt(i));
}

BArchivable*
Container::Instantiate(BMessage* archive)
{
	if (validate_instantiation(archive, "Container"))
		return new Container(archive);
	return NULL;
}

status_t
Container::Archive(BMessage* archive, bool deep) const
{
	status_t result = BArchivable::Archive(archive, deep);
	if (result != B_OK)
		return result;

	archive->AddString("name", fName);
	archive->AddString("class", "Container");

	if (deep) {
		BArchiver archiver(archive);
		for (int32 i = 0; i < fChildren.CountItems(); i++) {
			Container* child = static_cast<Container*>(fChildren.ItemAt(i));
			result = archiver.AddArchivable("children", child);
			if (result != B_OK)
				return result;
		}
	}

	return B_OK;
}

status_t
Container::AllUnarchived(const BMessage* archive, BUnarchiver* unarchiver)
{
	status_t result = BArchivable::AllUnarchived(archive, unarchiver);
	if (result != B_OK)
		return result;

	int32 index = 0;
	while (true) {
		Container* child = NULL;
		result = unarchiver->FindObject("children", index,
			BUnarchiver::B_DONT_ASSUME_OWNERSHIP, &child);
		if (result != B_OK)
			break;
		if (child != NULL)
			fChildren.AddItem(child);
		index++;
	}

	return B_OK;
}

void
Container::AddChild(Container* child)
{
	fChildren.AddItem(child);
}

void
Container::PrintToStream() const
{
	printf("Container: %s (%d children)\n", fName.String(),
		(int)fChildren.CountItems());
	for (int32 i = 0; i < fChildren.CountItems(); i++)
		static_cast<Container*>(fChildren.ItemAt(i))->PrintToStream();
}
