#include <Application.h>
#include <Autolock.h>
#include <LayoutBuilder.h>
#include <Window.h>
#include <Button.h>
#include <stdio.h>

class MyWindow : public BWindow
{
public:
	MyWindow()
		:
		BWindow(BRect(100, 100, 400, 300), "BAutolock Demo",
			B_TITLED_WINDOW, B_QUIT_ON_WINDOW_CLOSE)
	{
		BButton* button = new BButton("Click Me", new BMessage('CLCK'));

		BLayoutBuilder::Group<>(this, B_VERTICAL)
			.SetInsets(B_USE_DEFAULT_SPACING)
			.Add(button)
			.End();
	}

	void MessageReceived(BMessage* message)
	{
		switch (message->what) {
			case 'CLCK':
			{
				BAutolock locker(this);
				if (locker.IsLocked())
					printf("Window is locked within this scope\n");
			}
			printf("Window is unlocked after scope exits\n");
			break;

			default:
				BWindow::MessageReceived(message);
		}
	}
};

