#include "CanvasView.h"

#include <View.h>

CanvasView::CanvasView()
	:
	BView("canvas", B_WILL_DRAW | B_FULL_UPDATE_ON_RESIZE),
	fOffscreen(NULL)
{
	SetViewColor(B_TRANSPARENT_COLOR);
}

CanvasView::~CanvasView()
{
	delete fOffscreen;
}

void
CanvasView::Draw(BRect updateRect)
{
	BRect bounds = Bounds();

	if (fOffscreen == NULL || fOffscreen->Bounds() != bounds) {
		delete fOffscreen;
		fOffscreen = new BBitmap(bounds, B_RGB32, true);
		_RenderOffscreen();
	}

	DrawBitmap(fOffscreen, bounds);
}

void
CanvasView::_RenderOffscreen()
{
	BView* view = new BView(fOffscreen->Bounds(), "offscreen_view",
		B_FOLLOW_ALL, B_WILL_DRAW);

	fOffscreen->AddChild(view);
	fOffscreen->Lock();

	view->SetHighColor(30, 30, 30);
	view->FillRect(view->Bounds());

	view->SetHighColor(255, 80, 0);
	view->FillEllipse(view->Bounds().InsetByCopy(20, 20));

	view->SetHighColor(255, 255, 255);
	view->SetFontSize(24);
	view->DrawString("Offscreen!", BPoint(80, 120));

	view->Sync();
	fOffscreen->Unlock();
	fOffscreen->RemoveChild(view);

	delete view;
}
