```cpp
#include <Application.h>
#include <Bitmap.h>
#include <GraphicsDefs.h>
#include <View.h>
#include <stdio.h>

int main()
{
	BApplication app("application/x-vnd.bitmap-resize-example");

	// Создаём исходный bitmap
	BBitmap* source = new BBitmap(BRect(0, 0, 255, 255), B_RGB32);

	// Заполняем градиентом (B_RGB32 = BGRA!)
	uint8* bits = (uint8*)source->Bits();
	uint32 bytesPerRow = source->BytesPerRow();
	for (int y = 0; y <= 255; y++) {
		for (int x = 0; x <= 255; x++) {
			uint8* pixel = bits + y * bytesPerRow + x * 4;
			pixel[0] = 128;   // Blue
			pixel[1] = y;     // Green
			pixel[2] = x;     // Red
			pixel[3] = 255;   // Alpha
		}
	}

	// Масштабирование через BView и DrawBitmap
	BBitmap* resized = new BBitmap(BRect(0, 0, 127, 127), 
		B_BITMAP_ACCEPTS_VIEWS, B_RGB32);

	BView* view = new BView(resized->Bounds(), "offscreen", B_FOLLOW_NONE, 0);
	resized->AddChild(view);

	resized->Lock();
	view->DrawBitmap(source, source->Bounds(), resized->Bounds());
	view->Sync();
	resized->Unlock();

	resized->RemoveChild(view);
	delete view;

	// Конвертация цветового пространства через DrawBitmap
	BBitmap* converted = new BBitmap(BRect(0, 0, 127, 127), 
		B_BITMAP_ACCEPTS_VIEWS, B_GRAY8);

	BView* view2 = new BView(converted->Bounds(), "offscreen2", B_FOLLOW_NONE, 0);
	converted->AddChild(view2);

	converted->Lock();
	view2->DrawBitmap(resized, resized->Bounds(), converted->Bounds());
	view2->Sync();
	converted->Unlock();

	converted->RemoveChild(view2);
	delete view2;

	printf("Source: %ldx%ld, color space: %d\n",
		(long)(source->Bounds().Width() + 1),
		(long)(source->Bounds().Height() + 1),
		(int)source->ColorSpace());

	printf("Resized: %ldx%ld, color space: %d\n",
		(long)(resized->Bounds().Width() + 1),
		(long)(resized->Bounds().Height() + 1),
		(int)resized->ColorSpace());

	printf("Converted: %ldx%ld, color space: %d\n",
		(long)(converted->Bounds().Width() + 1),
		(long)(converted->Bounds().Height() + 1),
		(int)converted->ColorSpace());

	delete source;
	delete resized;
	delete converted;

	return 0;
}
