	if (bitmap == NULL) {
		bitmap = new BBitmap(BRect(0, 0, 63, 63), B_RGB32);
		memset(bitmap->Bits(), 0x80, bitmap->BitsLength());
	}

	BBitmapStream stream(bitmap);

	BFile outFile("/tmp/output_bitmap.png", B_WRITE_ONLY | B_CREATE_FILE | B_ERASE_FILE);
	if (outFile.InitCheck() != B_OK) {
		printf("Failed to create output file\n");
		return 1;
	}

	BTranslatorRoster* roster = BTranslatorRoster::Default();

	status_t result = roster->Translate(&stream, NULL, NULL, &outFile, B_PNG_FORMAT);
	if (result == B_OK)
		printf("Bitmap translated and saved to /tmp/output_bitmap.png\n");
	else
		printf("Translation failed: %s\n", strerror(result));

	BBitmap* detached = NULL;
	stream.DetachBitmap(&detached);
	delete detached;

	return 0;
}
