```cpp
#include "MyProducer.h"

#include <BufferGroup.h>
#include <string.h>

MyProducer::MyProducer()
	:
	BBufferProducer(B_MEDIA_RAW_AUDIO),
	fBufferGroup(NULL),
	fOutputEnabled(true)
{
	fOutput.node = Node();
	fOutput.source.port = ControlPort();
	fOutput.source.id = 0;
	fOutput.destination = media_destination::null;
	fOutput.format.type = B_MEDIA_RAW_AUDIO;
	fOutput.format.u.raw_audio = media_raw_audio_format::wildcard;
	strlcpy(fOutput.name, "MyProducer Output", B_MEDIA_NAME_LENGTH);
}

MyProducer::~MyProducer()
{
	delete fBufferGroup;
}

status_t
MyProducer::FormatSuggestionRequested(media_type type, int32 quality,
	media_format* format)
{
	if (type != B_MEDIA_RAW_AUDIO)
		return B_MEDIA_BAD_FORMAT;

	format->type = B_MEDIA_RAW_AUDIO;
	format->u.raw_audio = media_raw_audio_format::wildcard;
	return B_OK;
}

status_t
MyProducer::FormatProposal(const media_source& output, media_format* format)
{
	if (output != fOutput.source)
		return B_MEDIA_BAD_SOURCE;

	if (format->type != B_MEDIA_RAW_AUDIO)
		return B_MEDIA_BAD_FORMAT;

	return B_OK;
}

status_t
MyProducer::FormatChangeRequested(const media_source& source,
	const media_destination& destination, media_format* format,
	int32* changeTag)
{
	return B_ERROR;
}

status_t
MyProducer::GetNextOutput(int32* cookie, media_output* output)
{
	if (*cookie == 0) {
		*output = fOutput;
		*cookie = 1;
		return B_OK;
	}
	return B_BAD_INDEX;
}

status_t
MyProducer::DisposeOutputCookie(int32 cookie)
{
	return B_OK;
}

status_t
MyProducer::SetBufferGroup(const media_source& source, BBufferGroup* group)
{
	if (source != fOutput.source)
		return B_MEDIA_BAD_SOURCE;

	delete fBufferGroup;
	fBufferGroup = group;
	return B_OK;
}

status_t
MyProducer::PrepareToConnect(const media_source& source,
	const media_destination& destination, media_format* format,
	media_source* outSource, char* outName)
{
	if (source != fOutput.source)
		return B_MEDIA_BAD_SOURCE;

	if (fOutput.destination != media_destination::null)
		return B_MEDIA_ALREADY_CONNECTED;

	*outSource = fOutput.source;
	strlcpy(outName, fOutput.name, B_MEDIA_NAME_LENGTH);
	return B_OK;
}

void
MyProducer::Connect(status_t error, const media_source& source,
	const media_destination& destination, const media_format& format,
	char* ioName)
{
	if (error != B_OK)
		return;

	fOutput.destination = destination;
	fOutput.format = format;
	strlcpy(ioName, fOutput.name, B_MEDIA_NAME_LENGTH);
}

void
MyProducer::Disconnect(const media_source& source,
	const media_destination& destination)
{
	if (source != fOutput.source)
		return;

	fOutput.destination = media_destination::null;
	fOutput.format.type = B_MEDIA_RAW_AUDIO;
	fOutput.format.u.raw_audio = media_raw_audio_format::wildcard;
}

void
