public:
	MainWindow()
		:
		BWindow(BRect(100, 100, 400, 300), "CardLayout Switch",
			B_TITLED_WINDOW, B_QUIT_ON_WINDOW_CLOSE)
	{
		fCardLayout = new BCardLayout();
		BView* cardView = new BView("cards", 0, fCardLayout);

		BLayoutBuilder::Group<>(this, B_VERTICAL)
			.Add(cardView)
			.AddGroup(B_HORIZONTAL)
				.Add(new BButton("Prev", "Previous", new BMessage(kMsgPrev)))
				.Add(new BButton("Next", "Next", new BMessage(kMsgNext)))
			.End()
		.End();

		BLayoutBuilder::Cards<>(fCardLayout)
			.Add(new BStringView("s1", "Card One"))
			.Add(new BStringView("s2", "Card Two"))
			.Add(new BStringView("s3", "Card Three"));

		fCardLayout->SetVisibleItem((int32)0);
	}

	void MessageReceived(BMessage* message)
	{
		switch (message->what) {
			case kMsgNext:
			{
				int32 index = fCardLayout->VisibleIndex();
				if (index + 1 < fCardLayout->CountItems())
					fCardLayout->SetVisibleItem(index + 1);
				break;
			}
			case kMsgPrev:
			{
				int32 index = fCardLayout->VisibleIndex();
				if (index - 1 >= 0)
					fCardLayout->SetVisibleItem(index - 1);
				break;
			}
			default:
				BWindow::MessageReceived(message);
		}
	}

private:
	BCardLayout* fCardLayout;
};

