```cpp
#include <Application.h>
#include <Collator.h>
#include <Locale.h>
#include <LocaleRoster.h>
#include <String.h>
#include <stdio.h>

int
main()
{
	new BApplication("application/x-vnd.example-collator");

	BCollator collator;
	BLocale locale;
	BLocaleRoster::Default()->GetDefaultLocale(&locale);
	locale.GetCollator(&collator);

	const char* words[] = { "banana", "apple", "cherry", "avocado" };
	int count = 4;

	BString keys[4];
	for (int i = 0; i < count; i++)
		collator.GetSortKey(words[i], &keys[i]);

	for (int i = 0; i < count - 1; i++) {
		for (int j = i + 1; j < count; j++) {
			if (keys[i] > keys[j]) {
				BString tmpKey = keys[i];
				keys[i] = keys[j];
				keys[j] = tmpKey;

				const char* tmpWord = words[i];
				words[i] = words[j];
				words[j] = tmpWord;
			}
		}
	}

	printf("Sorted words:\n");
	for (int i = 0; i < count; i++)
		printf("  %s\n", words[i]);

	return 0;
}
