### BufferIO.cpp
```cpp
#include "BufferIO.h"

#include <string.h>

BufferIO::BufferIO()
	:
	fReadPos(0)
{
}

BufferIO::~BufferIO()
{
}

ssize_t
BufferIO::Read(void* buffer, size_t size)
{
	size_t available = fData.size() - fReadPos;
	if (available == 0)
		return 0;

	size_t toRead = size < available ? size : available;
	memcpy(buffer, fData.data() + fReadPos, toRead);
	fReadPos += toRead;
	return (ssize_t)toRead;
}

ssize_t
BufferIO::Write(const void* buffer, size_t size)
{
	const uint8* src = static_cast<const uint8*>(buffer);
	fData.insert(fData.end(), src, src + size);
	return (ssize_t)size;
}

const uint8*
BufferIO::Data() const
{
	return fData.data();
}

size_t
BufferIO::DataSize() const
{
	return fData.size();
}
