	ssize_t sent = sender.Send(message, strlen(message));
	printf("Sent %zd bytes\n", sent);

	char buffer[256];
	memset(buffer, 0, sizeof(buffer));
	BNetworkAddress from;
	ssize_t received = receiver.ReceiveFrom(buffer, sizeof(buffer) - 1, from);
	if (received >= 0) {
		printf("Received %zd bytes from %s: %s\n",
			received, from.ToString().String(), buffer);
	} else {
		printf("Receive failed or timed out\n");
	}

	return 0;
