### DirectWindow.cpp
```cpp
#include "DirectWindow.h"

#include <stdio.h>
#include <string.h>

DirectWindow::DirectWindow()
	:
	BDirectWindow(BRect(100, 100, 500, 400), "DirectWindow Example",
		B_TITLED_WINDOW, B_QUIT_ON_WINDOW_CLOSE),
	fBufferInfo(NULL),
	fConnected(false),
	fConnectionDisabled(false)
{
	fSemaphore = create_sem(1, "direct_sem");
	fBufferInfo = (direct_buffer_info*)malloc(
		DIRECT_BUFFER_INFO_AREA_SIZE);
}

DirectWindow::~DirectWindow()
{
	fConnectionDisabled = true;
	Hide();
	Snooze(50000);

	delete_sem(fSemaphore);
	free(fBufferInfo);
}

void
DirectWindow::DirectConnected(direct_buffer_info* info)
{
	if (fConnectionDisabled)
		return;

	acquire_sem(fSemaphore);

	switch (info->buffer_state & B_DIRECT_MODE_MASK) {
		case B_DIRECT_START:
			fConnected = true;
			memcpy(fBufferInfo, info, DIRECT_BUFFER_INFO_AREA_SIZE);
			printf("DirectConnected: START\n");
			printf("  bits: %p\n", fBufferInfo->bits);
			printf("  bytes_per_row: %lu\n", fBufferInfo->bytes_per_row);
			printf("  width: %d, height: %d\n",
				(int)fBufferInfo->window_bounds.right,
				(int)fBufferInfo->window_bounds.bottom);
			break;

		case B_DIRECT_MODIFY:
			memcpy(fBufferInfo, info, DIRECT_BUFFER_INFO_AREA_SIZE);
			printf("DirectConnected: MODIFY\n");
			break;

		case B_DIRECT_STOP:
			fConnected = false;
			printf("DirectConnected: STOP\n");
			break;
	}

	release_sem(fSemaphore);
}

bool
DirectWindow::QuitRequested()
{
	return true;
}
