#include <Application.h>
#include <Flattenable.h>
#include <DataIO.h>
#include <stdio.h>
#include <string.h>

class MyData : public BFlattenable
{
public:
	MyData(int32 value) : fValue(value) {}

	bool	IsFixedSize() const override { return true; }
	type_code	TypeCode() const override { return B_INT32_TYPE; }
	ssize_t		FlattenedSize() const override { return sizeof(int32); }

	status_t	Flatten(void* buffer, ssize_t size) const override
	{
		if (size < (ssize_t)sizeof(int32))
			return B_NO_MEMORY;
		memcpy(buffer, &fValue, sizeof(int32));
		return B_OK;
	}

	status_t	Unflatten(type_code code, const void* buffer, ssize_t size) override
	{
		if (size < (ssize_t)sizeof(int32))
			return B_BAD_VALUE;
		memcpy(&fValue, buffer, sizeof(int32));
		return B_OK;
	}

	int32	Value() const { return fValue; }

private:
	int32	fValue;
};

int
main()
{
	MyData original(42);

	BMemoryIO stream(original.FlattenedSize());
	status_t result = original.Flatten(&stream);

	printf("Flatten result: %s\n", strerror(result));

	stream.Seek(0, SEEK_SET);

	MyData restored(0);
	const void* buffer;
	off_t size = stream.BufferLength();
	buffer = ((BMallocIO*)nullptr);

	char readBuffer[sizeof(int32)];
	stream.Read(readBuffer, sizeof(int32));

	restored.Unflatten(B_INT32_TYPE, readBuffer, sizeof(int32));

	printf("Original value: %" B_PRId32 "\n", original.Value());
	printf("Restored value: %" B_PRId32 "\n", restored.Value());

	return 0;
}
