const char* kText = "Hello";

class GlyphView : public BView {
public:
	GlyphView()
		:
		BView("glyphview", B_WILL_DRAW)
	{
	}

	void Draw(BRect updateRect)
	{
		BFont font;
		GetFont(&font);

		int32 charCount = strlen(kText);
		BRect boxes[charCount];
		int32 numChars[1] = { charCount };

		font.GetBoundingBoxesForStrings(
			&kText, 1, B_SCREEN_METRIC, NULL, boxes);

		printf("Bounding box for \"%s\": "
			"left=%.1f top=%.1f right=%.1f bottom=%.1f\n",
			kText,
			boxes[0].left, boxes[0].top,
			boxes[0].right, boxes[0].bottom);

		BPoint glyphPositions[charCount];
		BRect glyphBoxes[charCount];
		for (int32 i = 0; i < charCount; i++)
			glyphPositions[i].Set(10 + i * 14, 50);

		font.GetBoundingBoxesAsGlyphs(
			kText, charCount, B_SCREEN_METRIC, glyphBoxes);

		SetHighColor(255, 0, 0);
		for (int32 i = 0; i < charCount; i++) {
			BRect r = glyphBoxes[i];
			r.OffsetBy(glyphPositions[i]);
			StrokeRect(r);
		}

		SetHighColor(0, 0, 0);
		MovePenTo(10, 50);
		DrawString(kText);
	}
};

class GlyphWindow : public BWindow {
public:
	GlyphWindow()
		:
		BWindow(BRect(100, 100, 400, 200), "BoundingBoxes",
			B_TITLED_WINDOW, B_QUIT_ON_WINDOW_CLOSE)
