static const uint32 kMsgRender = 'rndr';

GLWindow::GLWindow()
	:
	BWindow(BRect(100, 100, 500, 400), "BGLView Example",
		B_TITLED_WINDOW, B_AUTO_UPDATE_SIZE_LIMITS)
{
	fGLView = new BGLView(BRect(0, 0, 400, 300), "glview",
		B_FOLLOW_ALL, B_WILL_DRAW, BGL_RGB | BGL_DOUBLE | BGL_DEPTH);

	BLayoutBuilder::Group<>(this, B_VERTICAL, 0)
		.Add(fGLView)
		.End();

	PostMessage(kMsgRender);
}

GLWindow::~GLWindow()
{
}

void
GLWindow::MessageReceived(BMessage* message)
{
	switch (message->what) {
		case kMsgRender:
			_Render();
			break;

		default:
			BWindow::MessageReceived(message);
			break;
	}
}

bool
GLWindow::QuitRequested()
{
	be_app->PostMessage(B_QUIT_REQUESTED);
	return true;
}

void
GLWindow::_Render()
{
	fGLView->LockGL();

	glClearColor(0.1f, 0.2f, 0.4f, 1.0f);
	glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);

	glBegin(GL_TRIANGLES);
		glColor3f(1.0f, 0.0f, 0.0f);
		glVertex2f(0.0f, 0.5f);
		glColor3f(0.0f, 1.0f, 0.0f);
		glVertex2f(-0.5f, -0.5f);
		glColor3f(0.0f, 0.0f, 1.0f);
		glVertex2f(0.5f, -0.5f);
	glEnd();

	fGLView->SwapBuffers();

	fGLView->UnlockGL();
}
