void
GLView::AttachedToWindow()
{
	BGLView::AttachedToWindow();

	LockGL();

	glClearColor(0.1f, 0.1f, 0.2f, 1.0f);
	Reshape(Bounds().Width(), Bounds().Height());

	UnlockGL();
}

void
GLView::FrameResized(float width, float height)
{
	BGLView::FrameResized(width, height);

	LockGL();
	Reshape(width, height);
	UnlockGL();

	Draw(Bounds());
}

void
GLView::Draw(BRect updateRect)
{
	LockGL();

	glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);

	glBegin(GL_TRIANGLES);
		glColor3f(1.0f, 0.0f, 0.0f);
		glVertex2f( 0.0f,  0.5f);
		glColor3f(0.0f, 1.0f, 0.0f);
		glVertex2f(-0.5f, -0.5f);
		glColor3f(0.0f, 0.0f, 1.0f);
		glVertex2f( 0.5f, -0.5f);
	glEnd();

	SwapBuffers();

	UnlockGL();
}

void
GLView::Reshape(float width, float height)
{
	glViewport(0, 0, (GLsizei)width + 1, (GLsizei)height + 1);

	glMatrixMode(GL_PROJECTION);
	glLoadIdentity();

	float aspect = (height > 0) ? (width + 1.0f) / (height + 1.0f) : 1.0f;
	glOrtho(-aspect, aspect, -1.0, 1.0, -1.0, 1.0);

	glMatrixMode(GL_MODELVIEW);
	glLoadIdentity();
}
