### GLView.cpp
```cpp
#include "GLView.h"

#include <stdio.h>

GLView::GLView(BRect frame)
	:
	BGLView(frame, "GLView", B_FOLLOW_ALL, B_WILL_DRAW,
		BGL_RGB | BGL_DOUBLE | BGL_DEPTH),
	fOffsetX(0.0f),
	fOffsetY(0.0f)
{
}


GLView::~GLView()
{
}


void
GLView::AttachedToWindow()
{
	BGLView::AttachedToWindow();

	LockGL();
	glClearColor(0.1f, 0.1f, 0.2f, 1.0f);
	UnlockGL();
}


void
GLView::Draw(BRect updateRect)
{
	Render();
}


void
GLView::KeyDown(const char* bytes, int32 numBytes)
{
	switch (bytes[0]) {
		case B_LEFT_ARROW:
			fOffsetX -= 0.1f;
			break;
		case B_RIGHT_ARROW:
			fOffsetX += 0.1f;
			break;
		case B_UP_ARROW:
			fOffsetY += 0.1f;
			break;
		case B_DOWN_ARROW:
			fOffsetY -= 0.1f;
			break;
		default:
			BGLView::KeyDown(bytes, numBytes);
			return;
	}

	Render();
}


void
GLView::Render()
{
	LockGL();

	glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);

	glLoadIdentity();
	glTranslatef(fOffsetX, fOffsetY, -3.0f);

	glBegin(GL_TRIANGLES);
		glColor3f(1.0f, 0.0f, 0.0f);
		glVertex3f( 0.0f,  0.5f, 0.0f);
		glColor3f(0.0f, 1.0f, 0.0f);
		glVertex3f(-0.5f, -0.5f, 0.0f);
		glColor3f(0.0f, 0.0f, 1.0f);
		glVertex3f( 0.5f, -0.5f, 0.0f);
	glEnd();

	SwapBuffers();

	UnlockGL();
}
