	BApplication app("application/x-vnd.example-joystick");

	BJoystick joystick;

	int32 count = joystick.CountDevices();
	if (count == 0) {
		printf("No joystick devices found.\n");
		return 1;
	}

	char deviceName[B_OS_NAME_LENGTH];
	joystick.GetDeviceName(0, deviceName, sizeof(deviceName));
	printf("Opening device: %s\n", deviceName);

	if (joystick.Open(deviceName) < 0) {
		printf("Failed to open joystick.\n");
		return 1;
	}

	int32 axisCount = joystick.CountAxes();
	int32 buttonCount = joystick.CountButtons();
	printf("Axes: %ld, Buttons: %ld\n", axisCount, buttonCount);

	int16* axes = new int16[axisCount];

	for (int i = 0; i < 20; i++) {
		if (joystick.Update() == B_OK) {
			joystick.GetAxisValues(axes);
			uint32 buttons = joystick.ButtonValues();

			printf("Axes:");
			for (int32 a = 0; a < axisCount; a++)
				printf(" %d", axes[a]);
			printf("  Buttons: 0x%08lx\n", (unsigned long)buttons);
		}
		snooze(100000);
	}

	delete[] axes;
	joystick.Close();

	return 0;
}
