### ColorListItem.cpp
```cpp
#include "ColorListItem.h"

#include <View.h>
#include <Font.h>

ColorListItem::ColorListItem(const char* label, rgb_color color)
	:
	BListItem(),
	fLabel(label),
	fColor(color)
{
}

ColorListItem::~ColorListItem()
{
}

void
ColorListItem::DrawItem(BView* owner, BRect frame, bool complete)
{
	if (IsSelected() || complete) {
		rgb_color background = IsSelected()
			? ui_color(B_LIST_SELECTED_BACKGROUND_COLOR)
			: owner->ViewColor();
		owner->SetHighColor(background);
		owner->FillRect(frame);
	}

	float swatchSize = frame.Height() - 8.0f;
	BRect swatchRect(
		frame.left + 4.0f,
		frame.top + 4.0f,
		frame.left + 4.0f + swatchSize,
		frame.top + 4.0f + swatchSize
	);

	owner->SetHighColor(fColor);
	owner->FillRect(swatchRect);

	owner->SetHighColor(0, 0, 0, 255);
	owner->StrokeRect(swatchRect);

	rgb_color textColor = IsSelected()
		? ui_color(B_LIST_SELECTED_ITEM_TEXT_COLOR)
		: ui_color(B_LIST_ITEM_TEXT_COLOR);

	owner->SetHighColor(textColor);

	font_height fontHeight;
	owner->GetFontHeight(&fontHeight);

	float textY = frame.top
		+ (frame.Height() + fontHeight.ascent - fontHeight.descent) / 2.0f;

	owner->DrawString(fLabel.String(),
		BPoint(swatchRect.right + 8.0f, textY));
}

void
ColorListItem::Update(BView* owner, const BFont* font)
{
	BListItem::Update(owner, font);

	font_height fontHeight;
	font->GetHeight(&fontHeight);

	float itemHeight = fontHeight.ascent + fontHeight.descent
		+ fontHeight.leading + 8.0f;

	if (itemHeight < 24.0f)
		itemHeight = 24.0f;

	SetHeight(itemHeight);
}
