int32 gSharedValue = 0;

static int32
WorkerThread(void* data)
{
	int32 id = (int32)(addr_t)data;

	if (gLocker.Lock()) {
		gSharedValue++;
		printf("Thread %ld incremented value to %ld\n", id, gSharedValue);
		gLocker.Unlock();
	}

	return 0;
}

int
main()
{
	BApplication app("application/x-vnd.example-blocker");

	thread_id t1 = spawn_thread(WorkerThread, "worker1", B_NORMAL_PRIORITY, (void*)1);
	thread_id t2 = spawn_thread(WorkerThread, "worker2", B_NORMAL_PRIORITY, (void*)2);

	resume_thread(t1);
	resume_thread(t2);

	status_t result;
	wait_for_thread(t1, &result);
	wait_for_thread(t2, &result);

	printf("Final value: %ld\n", gSharedValue);

	return 0;
}
