#include <MediaFile.h>
#include <MediaTrack.h>
#include <Entry.h>
#include <Path.h>
#include <stdio.h>

int
main()
{
	entry_ref ref;
	BEntry entry("/tmp/output.wav", true);
	entry.GetRef(&ref);

	media_file_format fileFormat;
	memset(&fileFormat, 0, sizeof(fileFormat));

	int32 cookie = 0;
	while (get_next_file_format(&cookie, &fileFormat) == B_OK) {
		if (strcmp(fileFormat.short_name, "wav") == 0)
			break;
	}

	BMediaFile mediaFile(&ref, &fileFormat);
	if (mediaFile.InitCheck() != B_OK) {
		fprintf(stderr, "Failed to create media file\n");
		return 1;
	}

	media_format format;
	memset(&format, 0, sizeof(format));
	format.type = B_MEDIA_RAW_AUDIO;
	format.u.raw_audio.frame_rate = 44100;
	format.u.raw_audio.channel_count = 2;
	format.u.raw_audio.format = media_raw_audio_format::B_AUDIO_SHORT;
	format.u.raw_audio.byte_order = B_MEDIA_LITTLE_ENDIAN;
	format.u.raw_audio.buffer_size = 4096;

	BMediaTrack* track = mediaFile.CreateTrack(&format);
	if (track == NULL) {
		fprintf(stderr, "Failed to create media track\n");
		return 1;
	}

	mediaFile.CommitHeader();

	const int32 frameCount = 44100;
	const int32 bufferSize = 4096;
	int16 buffer[bufferSize / sizeof(int16)];
	memset(buffer, 0, bufferSize);

	int32 framesWritten = 0;
	int32 framesPerBuffer = bufferSize / (2 * sizeof(int16));

	while (framesWritten < frameCount) {
		int32 toWrite = framesPerBuffer;
		if (framesWritten + toWrite > frameCount)
			toWrite = frameCount - framesWritten;

		track->WriteFrames(buffer, toWrite);
		framesWritten += toWrite;
	}

	mediaFile.CloseFile();

	printf("Wrote %ld frames to /tmp/output.wav\n", (long)framesWritten);
	return 0;
}
