int
main()
	{
	BApplication app("application/x-vnd.example-mediaformat");

	media_format proposedFormat;
	media_format acceptedFormat;

	proposedFormat.type = B_MEDIA_RAW_AUDIO;
	proposedFormat.u.raw_audio.frame_rate = 44100;
	proposedFormat.u.raw_audio.channel_count = 2;
	proposedFormat.u.raw_audio.format = media_raw_audio_format::B_AUDIO_FLOAT;
	proposedFormat.u.raw_audio.byte_order = B_MEDIA_HOST_ENDIAN;
	proposedFormat.u.raw_audio.buffer_size = 4096;

	acceptedFormat = proposedFormat;

	BMediaFormats mediaFormats;
	status_t status = mediaFormats.InitCheck();
	if (status != B_OK) {
		printf("BMediaFormats init failed: %s\n", strerror(status));
		return 1;
	}

	media_format_description description;
	description.family = B_MISC_FORMAT_FAMILY;
	description.u.misc.file_format = 'RAW ';
	description.u.misc.codec = 'FLOT';

	status = mediaFormats.GetFormatFor(description, &acceptedFormat);
	if (status == B_OK) {
		printf("Negotiated format family: %d\n", acceptedFormat.type);
		printf("Frame rate: %.1f\n", acceptedFormat.u.raw_audio.frame_rate);
		printf("Channels: %ld\n", acceptedFormat.u.raw_audio.channel_count);
	} else {
