	if (status != B_OK || count < 1) {
		fprintf(stderr, "Could not get free output: %s\n", strerror(status));
		return 1;
	}

	status = roster->GetFreeInputsFor(audioOutput, &outputInput, 1, &count,
		media_type(B_MEDIA_RAW_AUDIO));
	if (status != B_OK || count < 1) {
		fprintf(stderr, "Could not get free input: %s\n", strerror(status));
		return 1;
	}

	media_output actualOutput;
	media_input actualInput;
	media_format format;
	format.type = B_MEDIA_RAW_AUDIO;

	status = roster->Connect(mixerOutput.source, outputInput.destination,
		&format, &actualOutput, &actualInput);
	if (status != B_OK) {
		fprintf(stderr, "Could not connect nodes: %s\n", strerror(status));
		return 1;
	}

	fprintf(stdout, "Nodes connected successfully\n");

	status = roster->Disconnect(actualOutput.node.node, actualOutput.source,
		actualInput.node.node, actualInput.destination);
