#include <MediaFile.h>
#include <MediaTrack.h>
#include <MediaFormats.h>
#include <entry.h>
#include <stdio.h>
#include <stdlib.h>

int
main(int argc, char* argv[])
{
	if (argc < 2) {
		fprintf(stderr, "Usage: %s <media_file>\n", argv[0]);
		return 1;
	}

	entry_ref ref;
	get_ref_for_path(argv[1], &ref);

	BMediaFile mediaFile(&ref);
	if (mediaFile.InitCheck() != B_OK) {
		fprintf(stderr, "Failed to open media file\n");
		return 1;
	}

	BMediaTrack* audioTrack = NULL;

	for (int32 i = 0; i < mediaFile.CountTracks(); i++) {
		BMediaTrack* track = mediaFile.TrackAt(i);
		media_format format;
		track->EncodedFormat(&format);

		if (format.IsAudio()) {
			audioTrack = track;
			break;
		}
		mediaFile.ReleaseTrack(track);
	}

	if (audioTrack == NULL) {
		fprintf(stderr, "No audio track found\n");
		return 1;
	}

	media_format decodedFormat;
	memset(&decodedFormat, 0, sizeof(decodedFormat));
	decodedFormat.type = B_MEDIA_RAW_AUDIO;
	decodedFormat.u.raw_audio.format = media_raw_audio_format::B_AUDIO_FLOAT;

	if (audioTrack->DecodedFormat(&decodedFormat) != B_OK) {
		fprintf(stderr, "Failed to set decoded format\n");
		mediaFile.ReleaseTrack(audioTrack);
		return 1;
	}

	size_t bufferSize = decodedFormat.u.raw_audio.buffer_size;
	char* buffer = new char[bufferSize];

	int64 framesRead = 0;
	int64 totalFrames = 0;
	status_t status = B_OK;

	while (status == B_OK) {
		status = audioTrack->ReadFrames(buffer, &framesRead);
		if (status == B_OK && framesRead > 0) {
			totalFrames += framesRead;
			printf("Read %lld frames (total: %lld)\n", framesRead, totalFrames);
		}
	}

	printf("Done. Total frames read: %lld\n", totalFrames);

	delete[] buffer;
	mediaFile.ReleaseTrack(audioTrack);

	return 0;
}
