		return 1;
	}

	entry_ref ref;
	get_ref_for_path(argv[1], &ref);

	BMediaFile mediaFile(&ref);
	if (mediaFile.InitCheck() != B_OK) {
		fprintf(stderr, "Failed to open media file\n");
		return 1;
	}

	BMediaTrack* videoTrack = NULL;
	media_format format;

	for (int32 i = 0; i < mediaFile.CountTracks(); i++) {
		BMediaTrack* track = mediaFile.TrackAt(i);
		memset(&format, 0, sizeof(format));
		track->EncodedFormat(&format);

		if (format.IsVideo()) {
			videoTrack = track;
			break;
		}

		mediaFile.ReleaseTrack(track);
	}

	if (videoTrack == NULL) {
		fprintf(stderr, "No video track found\n");
		return 1;
	}

	memset(&format, 0, sizeof(format));
	format.type = B_MEDIA_RAW_VIDEO;
	format.u.raw_video = media_raw_video_format::wildcard;

	if (videoTrack->DecodedFormat(&format) != B_OK) {
		fprintf(stderr, "Failed to set decoded format\n");
		mediaFile.ReleaseTrack(videoTrack);
		return 1;
	}

	int32 width = (int32)format.u.raw_video.display.line_width;
	int32 height = (int32)format.u.raw_video.display.line_count;
	int32 bytesPerRow = format.u.raw_video.display.bytes_per_row;

	printf("Video: %ldx%ld, bytes per row: %ld\n", width, height, bytesPerRow);
	printf("Frame count: %lld\n", videoTrack->CountFrames());

	size_t bufferSize = (size_t)(bytesPerRow * height);
	uint8* buffer = (uint8*)malloc(bufferSize);

	int64 frameCount = 0;
	int64 framesRead = 0;
	media_header header;

	while (videoTrack->ReadFrames(buffer, &framesRead, &header) == B_OK) {
		frameCount += framesRead;
		printf("Read frame %lld, time: %lld us\n", frameCount, header.start_time);
	}

	printf("Total frames read: %lld\n", frameCount);

	free(buffer);
	mediaFile.ReleaseTrack(videoTrack);

	return 0;
}
