#include <MediaFile.h>
#include <MediaTrack.h>
#include <MediaFormats.h>
#include <storage/File.h>
#include <stdio.h>
#include <string.h>

int
main()
{
	BFile file("output.wav", B_CREATE_FILE | B_WRITE_ONLY | B_ERASE_FILE);
	if (file.InitCheck() != B_OK) {
		fprintf(stderr, "Failed to open file\n");
		return 1;
	}

	media_file_format fileFormat;
	media_format_description formatDesc;
	BMediaFormats formats;

	memset(&fileFormat, 0, sizeof(fileFormat));
	strcpy(fileFormat.short_name, "wav");
	strcpy(fileFormat.mime_type, "audio/x-wav");
	fileFormat.family = B_WAV_FORMAT_FAMILY;

	BMediaFile mediaFile(&file, &fileFormat);
	if (mediaFile.InitCheck() != B_OK) {
		fprintf(stderr, "Failed to create media file\n");
		return 1;
	}

	media_format format;
	memset(&format, 0, sizeof(format));
	format.type = B_MEDIA_RAW_AUDIO;
	format.u.raw_audio.frame_rate = 44100;
	format.u.raw_audio.channel_count = 1;
	format.u.raw_audio.format = media_raw_audio_format::B_AUDIO_SHORT;
	format.u.raw_audio.byte_order = B_MEDIA_LITTLE_ENDIAN;
	format.u.raw_audio.buffer_size = 4096;

	BMediaTrack* track = mediaFile.CreateTrack(&format);
	if (track == NULL) {
		fprintf(stderr, "Failed to create track\n");
		return 1;
	}

	mediaFile.CommitHeader();

	const int32 kFrameCount = 44100;
	const int32 kBufferFrames = 512;
	int16 buffer[kBufferFrames];

	int32 framesWritten = 0;
	while (framesWritten < kFrameCount) {
		int32 toWrite = kBufferFrames;
		if (framesWritten + toWrite > kFrameCount)
			toWrite = kFrameCount - framesWritten;

		memset(buffer, 0, toWrite * sizeof(int16));

		status_t result = track->WriteFrames(buffer, toWrite);
		if (result != B_OK) {
			fprintf(stderr, "WriteFrames failed\n");
			break;
		}

		framesWritten += toWrite;
	}

	mediaFile.CloseFile();

	printf("Wrote %d frames\n", framesWritten);
	return 0;
}
