		fMenu->AddItem(new BMenuItem("First Item", new BMessage(kAddItem)));
		fMenu->AddItem(new BMenuItem("Second Item", new BMessage(kRemoveItem)));
		fMenu->AddItem(new BMenuItem("Third Item", NULL));

		BMenuBar* menuBar = new BMenuBar("menubar");
		menuBar->AddItem(fMenu);

		BLayoutBuilder::Group<>(this, B_VERTICAL, 0)
			.Add(menuBar)
			.AddGlue()
		.End();
