	void MessageReceived(BMessage* message)
	{
		switch (message->what) {
			case kAddItem:
				fMenu->AddItem(new BMenuItem("New Item", NULL));
				break;
			case kRemoveItem:
			{
				BMenuItem* item = fMenu->FindItem("Second Item");
				if (item != NULL) {
					fMenu->RemoveItem(item);
					delete item;
				}
				break;
			}
			default:
				BWindow::MessageReceived(message);
		}
	}

private:
