#include <Message.h>
#include <stdio.h>

int
main()
{
	BApplication app("application/x-vnd.example-messagequeue");

	BMessageQueue queue;

	BMessage* msgA = new BMessage('MSGA');
	msgA->AddString("content", "First");

	BMessage* msgB = new BMessage('MSGB');
	msgB->AddString("content", "Second");

	BMessage* msgC = new BMessage('MSGC');
	msgC->AddString("content", "Third");

	queue.AddMessage(msgA);
	queue.AddMessage(msgB);
	queue.AddMessage(msgC);

	printf("Queue count: %ld\n", queue.CountMessages());

	while (!queue.IsEmpty()) {
		BMessage* msg = queue.NextMessage();
		if (msg == NULL)
			break;

		const char* content = NULL;
		if (msg->FindString("content", &content) == B_OK)
			printf("Dequeued what='%.4s' content='%s'\n",
				(char*)&msg->what, content);

		delete msg;
	}

	printf("Queue count after drain: %ld\n", queue.CountMessages());

	return 0;
}
