#include <Application.h>
#include <MidiConsumer.h>
#include <MidiProducer.h>
#include <MidiRoster.h>
#include <stdio.h>

int
main()
{
	BApplication app("application/x-vnd.example-midi-connect");

	BMidiProducer* producer = NULL;
	BMidiConsumer* consumer = NULL;

	int32 id = 0;
	while ((producer = BMidiRoster::NextProducer(&id)) != NULL) {
		printf("Found producer: %s (id=%ld)\n", producer->Name(), producer->ID());
		break;
	}

	id = 0;
	while ((consumer = BMidiRoster::NextConsumer(&id)) != NULL) {
		printf("Found consumer: %s (id=%ld)\n", consumer->Name(), consumer->ID());
		break;
	}

	if (producer != NULL && consumer != NULL) {
		status_t err = producer->Connect(consumer);
		if (err == B_OK)
			printf("Connected producer to consumer\n");
		else
			printf("Connection failed: %s\n", strerror(err));

		producer->Disconnect(consumer);
	}

	if (producer != NULL)
