### ResolverWindow.cpp
```cpp
#include "ResolverWindow.h"

#include <Button.h>
#include <LayoutBuilder.h>
#include <NetworkAddress.h>
#include <StringView.h>
#include <stdio.h>

ResolverWindow::ResolverWindow()
	:
	BWindow(BRect(100, 100, 500, 300), "Async Resolver",
		B_TITLED_WINDOW, B_AUTO_UPDATE_SIZE_LIMITS)
{
	BStringView* label = new BStringView("label", "Resolving www.haiku-os.org ...");
	BButton* button = new BButton("quit", "Quit", new BMessage(B_QUIT_REQUESTED));

	BLayoutBuilder::Group<>(this, B_VERTICAL, B_USE_DEFAULT_SPACING)
		.SetInsets(B_USE_WINDOW_INSETS)
		.Add(label)
		.Add(button)
		.End();

	_StartResolve();
}

ResolverWindow::~ResolverWindow()
{
	fResolver.Cancel();
}

void
ResolverWindow::MessageReceived(BMessage* message)
{
	switch (message->what) {
		case kMsgResolved:
		{
			status_t status;
			if (message->FindInt32("error", (int32*)&status) == B_OK
					&& status != B_OK) {
				printf("Resolution failed: %s\n", strerror(status));
				break;
			}

			uint32 cookie = 0;
			BNetworkAddress address;
			while (fResolver.GetNextAddress(&cookie, address) == B_OK) {
				printf("Resolved: %s\n", address.ToString().String());
			}
			break;
		}
		default:
			BWindow::MessageReceived(message);
			break;
	}
}

bool
ResolverWindow::QuitRequested()
{
	fResolver.Cancel();
	be_app->PostMessage(B_QUIT_REQUESTED);
	return true;
}

void
ResolverWindow::_StartResolve()
{
	BMessenger messenger(this);
	BMessage notify(kMsgResolved);

	status_t status = fResolver.Resolve("www.haiku-os.org", NULL,
		B_NETWORK_ADDRESS_ANY, 0, messenger, notify);

	if (status != B_OK)
		printf("Failed to start resolution: %s\n", strerror(status));
}
