	BWindow(BRect(100, 100, 600, 400), "Node Monitor", B_TITLED_WINDOW,
		B_AUTO_UPDATE_SIZE_LIMITS)
{
	fTextView = new BTextView("log");
	fTextView->SetWordWrap(true);
	fTextView->MakeEditable(false);

	BScrollView* scrollView = new BScrollView("scroll", fTextView,
		0, false, true);

	BLayoutBuilder::Group<>(this, B_VERTICAL, 0)
		.Add(scrollView)
		.End();

	_StartWatching("/boot/home");
}

MonitorWindow::~MonitorWindow()
{
	watch_node(NULL, B_STOP_WATCHING, this);
}

void
MonitorWindow::MessageReceived(BMessage* message)
{
	switch (message->what) {
		case B_NODE_MONITOR:
		{
			int32 opcode;
			if (message->FindInt32("opcode", &opcode) == B_OK) {
				switch (opcode) {
					case B_ENTRY_CREATED:
					{
						const char* name;
						message->FindString("name", &name);
						BString msg("Created: ");
						msg << name << "\n";
						_LogMessage(msg.String());
						break;
					}
					case B_ENTRY_REMOVED:
					{
						const char* name;
						message->FindString("name", &name);
						BString msg("Removed: ");
						msg << name << "\n";
						_LogMessage(msg.String());
						break;
					}
					case B_ENTRY_MOVED:
					{
						const char* name;
						message->FindString("name", &name);
						BString msg("Moved: ");
						msg << name << "\n";
						_LogMessage(msg.String());
						break;
					}
					default:
						_LogMessage("Other node change\n");
						break;
				}
			}
			break;
		}
		default:
			BWindow::MessageReceived(message);
			break;
	}
}

bool
MonitorWindow::QuitRequested()
{
	be_app->PostMessage(B_QUIT_REQUESTED);
	return true;
}

void
MonitorWindow::_StartWatching(const char* path)
{
	BEntry entry(path);
	node_ref nref;
	entry.GetNodeRef(&nref);

	status_t status = watch_node(&nref, B_WATCH_DIRECTORY, this);

	BString msg;
	if (status == B_OK) {
		msg << "Watching: " << path << "\n";
	} else {
		msg << "Failed to watch: " << path << "\n";
	}
	_LogMessage(msg.String());
}

void
MonitorWindow::_LogMessage(const char* text)
{
	if (Lock()) {
		fTextView->Insert(fTextView->TextLength(), text, strlen(text));
		Unlock();
	}
}
