				BListItem* item = fOutlineListView->FullListItemAt(i);
				if (item->OutlineLevel() == 0)
					fOutlineListView->Expand(item);
			}
			break;

		case kCollapseAll:
			for (int32 i = 0; i < fOutlineListView->FullListCountItems(); i++) {
				BListItem* item = fOutlineListView->FullListItemAt(i);
				if (item->OutlineLevel() == 0)
					fOutlineListView->Collapse(item);
			}
			break;

		default:
			BWindow::MessageReceived(message);
			break;
	}
}
