MainWindow::~MainWindow()
{
}

void
MainWindow::MessageReceived(BMessage* message)
{
	switch (message->what) {
		case kMsgPageSetup:
		{
			BPrintJob job("example_document");
			if (job.ConfigPage() == B_OK) {
				BMessage* settings = job.Settings();
				if (settings != NULL) {
					BMessage copy(*settings);
					copy.PrintToStream();
				}
			}
			break;
		}
		case kMsgPrint:
			_DoPrint();
			break;
		default:
			BWindow::MessageReceived(message);
			break;
	}
}

void
MainWindow::_DoPrint()
{
	BPrintJob job("example_document");

	if (job.ConfigPage() != B_OK)
		return;

	if (job.ConfigJob() != B_OK)
		return;

	BRect pageRect = job.PrintableRect();
	int32 firstPage = job.FirstPage();
	int32 lastPage = job.LastPage();

	job.BeginJob();

	for (int32 page = firstPage; page <= lastPage; page++) {
		BView* view = new BView(pageRect, "print_view", B_FOLLOW_ALL, B_WILL_DRAW);
		AddChild(view);

		job.DrawView(view, pageRect, BPoint(0, 0));
		job.SpoolPage();

		RemoveChild(view);
		delete view;

		if (!job.CanContinue())
			break;
	}

	job.CommitJob();
}
