static property_info sPropertyList[] = {
	{
		"Title",
		{ B_GET_PROPERTY, B_SET_PROPERTY, 0 },
		{ B_DIRECT_SPECIFIER, 0 },
		"Get or set the window title",
		0
	},
	{
		"Frame",
		{ B_GET_PROPERTY, B_SET_PROPERTY, 0 },
		{ B_DIRECT_SPECIFIER, 0 },
		"Get or set the window frame",
		0
	},
	{
		"Hidden",
		{ B_GET_PROPERTY, B_SET_PROPERTY, 0 },
		{ B_DIRECT_SPECIFIER, 0 },
		"Get or set visibility",
		0
	},
	{ 0 }
};

class ScriptableWindow : public BWindow
{
public:
					ScriptableWindow()
						: BWindow(BRect(100, 100, 400, 300), "Scriptable Window",
							B_TITLED_WINDOW, B_QUIT_ON_WINDOW_CLOSE)
					{
						fPropertyInfo = new BPropertyInfo(sPropertyList);
					}

					~ScriptableWindow()
					{
						delete fPropertyInfo;
					}

	virtual BHandler*
					ResolveSpecifier(BMessage* message, int32 index,
						BMessage* specifier, int32 what, const char* property)
					{
						int32 match;
						uint32 data;

						if (fPropertyInfo->FindMatch(message, index, specifier,
								what, property, &data) >= 0) {
							return this;
						}

						return BWindow::ResolveSpecifier(message, index,
							specifier, what, property);
					}

	virtual void	MessageReceived(BMessage* message)
					{
						BMessage specifier;
						int32 index;
						int32 what;
						const char* property;
						uint32 data;

						if (message->GetCurrentSpecifier(&index, &specifier,
								&what, &property) != B_OK) {
							BWindow::MessageReceived(message);
							return;
						}

						if (fPropertyInfo->FindMatch(message, index, &specifier,
								what, property, &data) < 0) {
							BWindow::MessageReceived(message);
							return;
						}

						switch (message->what) {
							case B_GET_PROPERTY:
							{
								BMessage reply(B_REPLY);

								if (strcmp(property, "Title") == 0) {
									reply.AddString("result", Title());
								} else if (strcmp(property, "Frame") == 0) {
									reply.AddRect("result", Frame());
								} else if (strcmp(property, "Hidden") == 0) {
									reply.AddBool("result", IsHidden());
								}

								message->SendReply(&reply);
								break;
							}

							case B_SET_PROPERTY:
							{
								if (strcmp(property, "Title") == 0) {
									const char* title;
									if (message->FindString("data", &title) == B_OK)
										SetTitle(title);
								} else if (strcmp(property, "Hidden") == 0) {
									bool hidden;
									if (message->FindBool("data", &hidden) == B_OK) {
										if (hidden)
											Hide();
										else
											Show();
									}
								}

								BMessage reply(B_REPLY);
								message->SendReply(&reply);
								break;
							}

							default:
								BWindow::MessageReceived(message);
								break;
						}
					}

private:
	BPropertyInfo*	fPropertyInfo;
};

class App : public BApplication
{
public:
					App()
						: BApplication("application/x-vnd.example-propertyinfo")
					{
					}

	virtual void	ReadyToRun()
					{
						ScriptableWindow* window = new ScriptableWindow();
						window->Show();
					}
};

int
main()
{
	App app;
	app.Run();
	return 0;
}
