#include <Application.h>
#include <PushGameSound.h>
#include <math.h>
#include <stdio.h>

int
main()
{
	BApplication app("application/x-vnd.example-pushgamesound");

	const size_t frameCount = 4096;
	const int32 channelCount = 2;
	const float sampleRate = 44100.0f;

	gs_audio_format format;
	format.frame_rate = sampleRate;
	format.channel_count = channelCount;
	format.format = gs_audio_format::B_GS_F32;
	format.byte_order = B_MEDIA_LITTLE_ENDIAN;
	format.buffer_size = frameCount * channelCount * sizeof(float);

	BPushGameSound sound(frameCount, &format);

	if (sound.InitCheck() != B_OK) {
		fprintf(stderr, "BPushGameSound init failed\n");
		return 1;
	}

	sound.StartPlaying();

	float* buffer = new float[frameCount * channelCount];

	float phase = 0.0f;
	const float frequency = 440.0f;
	const float increment = 2.0f * M_PI * frequency / sampleRate;

	for (int32 iteration = 0; iteration < 100; iteration++) {
		for (size_t frame = 0; frame < frameCount; frame++) {
			float sample = sinf(phase) * 0.3f;
			buffer[frame * channelCount + 0] = sample;
			buffer[frame * channelCount + 1] = sample;
			phase += increment;
			if (phase >= 2.0f * M_PI)
				phase -= 2.0f * M_PI;
		}

		size_t byteCount = frameCount * channelCount * sizeof(float);
		while (sound.WriteFrames(buffer, frameCount) == B_WOULD_BLOCK)
			snooze(1000);
	}

	sound.StopPlaying();

	delete[] buffer;

	return 0;
}
