void
QueryMonitorApp::ReadyToRun()
{
	BVolumeRoster roster;
	BVolume bootVolume;
	roster.GetBootVolume(&bootVolume);

	fQuery.SetVolume(&bootVolume);
	fQuery.SetPredicate("name=*.txt");

	BMessenger messenger(this);
	fQuery.SetTarget(messenger);

	status_t status = fQuery.Fetch();
	if (status != B_OK) {
		printf("Failed to fetch query: %s\n", strerror(status));
		Quit();
		return;
	}

	printf("Live query started. Watching for *.txt file changes...\n");

	BEntry entry;
	while (fQuery.GetNextEntry(&entry) == B_OK) {
		char name[B_FILE_NAME_LENGTH];
		entry.GetName(name);
		printf("Existing match: %s\n", name);
	}
}

void
QueryMonitorApp::MessageReceived(BMessage* message)
{
	switch (message->what) {
		case B_QUERY_UPDATE:
		{
			int32 opcode;
			if (message->FindInt32("opcode", &opcode) != B_OK)
				break;

			const char* name;
			if (message->FindString("name", &name) != B_OK)
				name = "(unknown)";

			if (opcode == B_ENTRY_CREATED)
				printf("Live update: file created: %s\n", name);
			else if (opcode == B_ENTRY_REMOVED)
				printf("Live update: file removed: %s\n", name);

			break;
		}

		default:
			BApplication::MessageReceived(message);
			break;
	}
}
