	screen.GetMode(&currentMode);

	printf("Current mode: %ldx%ld\n",
		currentMode.virtual_width, currentMode.virtual_height);

	display_mode* modeList;
	uint32 modeCount;
	screen.GetModeList(&modeList, &modeCount);

	display_mode targetMode = currentMode;
	for (uint32 i = 0; i < modeCount; i++) {
		if (modeList[i].virtual_width == 1024
			&& modeList[i].virtual_height == 768) {
			targetMode = modeList[i];
			break;
		}
	}

	delete[] modeList;

	status_t result = screen.SetMode(&targetMode);
	if (result == B_OK) {
		printf("Mode set to: %ldx%ld\n",
			targetMode.virtual_width, targetMode.virtual_height);
	} else {
		printf("Failed to set mode: %s\n", strerror(result));
	}

	return 0;
}
