#include <SerialPort.h>
#include <stdio.h>
#include <string.h>

int
main()
{
	BSerialPort port;

	if (port.Open("/dev/ports/usb0") < B_OK) {
		fprintf(stderr, "Failed to open serial port\n");
		return 1;
	}

	port.SetDataRate(B_9600_BPS);
	port.SetDataBits(B_DATA_BITS_8);
	port.SetStopBits(B_STOP_BITS_1);
	port.SetParityMode(B_NO_PARITY);
	port.SetFlowControl(B_HARDWARE_CONTROL);

	const char* message = "Hello, serial port!";
	ssize_t written = port.Write(message, strlen(message));
	if (written < 0)
		fprintf(stderr, "Write failed\n");
	else
		printf("Wrote %zd bytes\n", written);

	char buffer[256];
	memset(buffer, 0, sizeof(buffer));

	port.SetBlocking(true);
	port.SetTimeout(1000000);

	ssize_t received = port.Read(buffer, sizeof(buffer) - 1);
	if (received < 0)
		fprintf(stderr, "Read failed\n");
	else
		printf("Received: %s\n", buffer);

	port.Close();
	return 0;
}
