class ShapePrinter : public BShapeIterator
{
public:
	status_t	IterateMoveTo(BPoint* point);
	status_t	IterateLineTo(int32 lineCount, BPoint* linePoints);
	status_t	IterateBezierTo(int32 bezierCount, BPoint* bezierPoints);
	status_t	IterateClose();
};


status_t
ShapePrinter::IterateMoveTo(BPoint* point)
{
	printf("MoveTo (%.1f, %.1f)\n", point->x, point->y);
	return B_OK;
}


status_t
ShapePrinter::IterateLineTo(int32 lineCount, BPoint* linePoints)
{
	for (int32 i = 0; i < lineCount; i++)
		printf("LineTo (%.1f, %.1f)\n", linePoints[i].x, linePoints[i].y);
	return B_OK;
}


status_t
ShapePrinter::IterateBezierTo(int32 bezierCount, BPoint* bezierPoints)
{
	for (int32 i = 0; i < bezierCount; i++) {
		BPoint* p = bezierPoints + i * 3;
		printf("BezierTo (%.1f,%.1f) (%.1f,%.1f) (%.1f,%.1f)\n",
			p[0].x, p[0].y, p[1].x, p[1].y, p[2].x, p[2].y);
	}
	return B_OK;
}


status_t
ShapePrinter::IterateClose()
{
	printf("Close\n");
	return B_OK;
}


int
main()
{
	BShape shape;

	shape.MoveTo(BPoint(10, 10));
	shape.LineTo(BPoint(100, 10));
	shape.LineTo(BPoint(100, 100));

	BPoint bezierPts[3] = {
		BPoint(80, 150),
		BPoint(20, 150),
		BPoint(10, 100)
	};
	shape.BezierTo(bezierPts);
	shape.Close();

	ShapePrinter printer;
	printer.Iterate(&shape);

	return 0;
}
