#include <Application.h>
#include <NetworkKit.h>
#include <stdio.h>

int
main()
{
	BNetworkAddress address("example.com", 80);
	BSocket socket;

	status_t status = socket.Connect(address);
	if (status != B_OK) {
		fprintf(stderr, "Connect failed: %s\n", strerror(status));
		return 1;
	}

	printf("Connected successfully\n");

	const char* request = "GET / HTTP/1.0\r\nHost: example.com\r\n\r\n";
	ssize_t written = socket.Write(request, strlen(request));
	if (written < 0) {
		fprintf(stderr, "Write failed: %s\n", strerror((status_t)written));
		socket.Disconnect();
		return 1;
	}

	char buffer[512];
	ssize_t bytesRead;
	while ((bytesRead = socket.Read(buffer, sizeof(buffer) - 1)) > 0) {
		buffer[bytesRead] = '\0';
		printf("%s", buffer);
	}

	if (bytesRead < 0) {
		status_t readError = (status_t)bytesRead;
		if (readError != B_CANCELED)
			fprintf(stderr, "Read error: %s\n", strerror(readError));
	}

	status = socket.Disconnect();
	if (status != B_OK)
		fprintf(stderr, "Disconnect failed: %s\n", strerror(status));
	else
		printf("\nDisconnected cleanly\n");

