#include <Application.h>
#include <SoundPlayer.h>
#include <math.h>
#include <stdio.h>

static double sPhase = 0.0;
static const double kFrequency = 440.0;
static const double kSampleRate = 44100.0;
static const double kAmplitude = 0.3;

void
PlayBuffer(void* cookie, void* buffer, size_t size, const media_raw_audio_format& format)
{
	float* samples = (float*)buffer;
	size_t frameCount = size / sizeof(float);

	for (size_t i = 0; i < frameCount; i++) {
		samples[i] = (float)(kAmplitude * sin(sPhase));
		sPhase += 2.0 * M_PI * kFrequency / kSampleRate;
		if (sPhase >= 2.0 * M_PI)
			sPhase -= 2.0 * M_PI;
	}
}

int
