public:
	MainWindow();
	virtual void			MessageReceived(BMessage* message);

private:
	BStatusBar*				fStatusBar;
};

MainWindow::MainWindow()
	:
	BWindow(BRect(100, 100, 400, 250), "BStatusBar Update",
		B_TITLED_WINDOW, B_QUIT_ON_WINDOW_CLOSE)
{
	fStatusBar = new BStatusBar("progress", "Progress: ", "done");
	fStatusBar->SetMaxValue(100.0f);

	BLayoutBuilder::Group<>(this, B_VERTICAL, B_USE_DEFAULT_SPACING)
		.SetInsets(B_USE_WINDOW_INSETS)
		.Add(fStatusBar)
		.AddGroup(B_HORIZONTAL)
			.Add(new BButton("Update", new BMessage(kMsgUpdate)))
			.Add(new BButton("Reset", new BMessage(kMsgReset)))
		.End()
	.End();
}

void
MainWindow::MessageReceived(BMessage* message)
{
	switch (message->what) {
		case kMsgUpdate:
		{
			float delta = 10.0f;
			BString trailingText;
			trailingText.SetToFormat("%.0f%%", fStatusBar->CurrentValue() + delta);
			fStatusBar->Update(delta, NULL, trailingText.String());
			break;
		}
		case kMsgReset:
			fStatusBar->Reset("Progress: ", "done");
			break;
		default:
			BWindow::MessageReceived(message);
			break;
	}
}

class App : public BApplication {
public:
	App() : BApplication("application/x-vnd.example-statusbar") {}
	void ReadyToRun() override { (new MainWindow())->Show(); }
};

