#include <Application.h>
#include <StreamingGameSound.h>
#include <math.h>
#include <stdio.h>
#include <string.h>

static const int32 kSampleRate = 44100;
static const int32 kBufferSize = 4096;
static float sPhase = 0.0f;

void
StreamingCallback(void* cookie, void* buffer, size_t byteCount,
	const gs_audio_format* format)
{
	int16* samples = (int16*)buffer;
	size_t frameCount = byteCount / (sizeof(int16) * format->channel_count);

	for (size_t i = 0; i < frameCount; i++) {
		int16 sample = (int16)(sinf(sPhase) * 32767.0f);
		for (int32 ch = 0; ch < format->channel_count; ch++)
			samples[i * format->channel_count + ch] = sample;
		sPhase += 2.0f * M_PI * 440.0f / kSampleRate;
		if (sPhase > 2.0f * M_PI)
			sPhase -= 2.0f * M_PI;
	}
}

int
main()
{
	BApplication app("application/x-vnd.example-streamingsound");

	gs_audio_format format;
	memset(&format, 0, sizeof(format));
	format.frame_rate = kSampleRate;
	format.channel_count = 2;
	format.format = gs_audio_format::B_GS_S16;
	format.byte_order = B_MEDIA_LITTLE_ENDIAN;
	format.buffer_size = kBufferSize;

	BStreamingGameSound* sound = new BStreamingGameSound(
		kBufferSize, &format, 2, NULL);

	if (sound->InitCheck() != B_OK) {
		fprintf(stderr, "Failed to initialize BStreamingGameSound\n");
		delete sound;
		return 1;
	}

	sound->SetStreamHook(StreamingCallback, NULL);
	sound->StartPlaying();

	snooze(3000000);

	sound->StopPlaying();
	delete sound;

	return 0;
}
