#include "MainWindow.h"

#include <LayoutBuilder.h>
#include <TextView.h>

class DigitsOnlyFilter : public BTextView::filter_t {
public:
	static filter_result
	Filter(BMessage* message, BHandler** handler, BMessageFilter* filter)
	{
		const char* bytes;
		int32 numBytes;
		message->FindData("bytes", B_STRING_TYPE,
			(const void**)&bytes, &numBytes);

		if (numBytes > 0) {
			for (int32 i = 0; i < numBytes; i++) {
				if (!isdigit(bytes[i]) && bytes[i] != B_BACKSPACE
					&& bytes[i] != B_DELETE) {
					return B_SKIP_MESSAGE;
				}
			}
		}
		return B_DISPATCH_MESSAGE;
	}
};

MainWindow::MainWindow()
	:
	BWindow(BRect(100, 100, 400, 200), "TextControl Filter",
		B_TITLED_WINDOW, B_QUIT_ON_WINDOW_CLOSE)
{
	BTextControl* textControl = new BTextControl("Numbers only:", "", nullptr);

	textControl->TextView()->AddFilter(
		new BMessageFilter(B_KEY_DOWN, DigitsOnlyFilter::Filter));

	BLayoutBuilder::Group<>(this, B_VERTICAL, B_USE_DEFAULT_SPACING)
