status_t
MyTranslator::Identify(BPositionIO* inSource,
	const translation_format* inFormat,
	BMessage* ioExtension,
	translator_info* outInfo,
	uint32 outType)
{
	if (outType != 0 && outType != B_TRANSLATOR_TEXT)
		return B_NO_TRANSLATOR;

	outInfo->type = B_TRANSLATOR_TEXT;
	outInfo->group = B_TRANSLATOR_TEXT;
	outInfo->quality = 0.4f;
	outInfo->capability = 0.4f;
	strlcpy(outInfo->name, "Plain Text", sizeof(outInfo->name));
	strlcpy(outInfo->MIME, "text/plain", sizeof(outInfo->MIME));

	return B_OK;
}


status_t
MyTranslator::Translate(BPositionIO* inSource,
	const translator_info* inInfo,
	BMessage* ioExtension,
	uint32 outType,
	BPositionIO* outDestination)
{
	if (outType != B_TRANSLATOR_TEXT)
		return B_NO_TRANSLATOR;

	char buffer[4096];
	ssize_t bytesRead;

	while ((bytesRead = inSource->Read(buffer, sizeof(buffer))) > 0)
		outDestination->Write(buffer, bytesRead);

	return B_OK;
}
