int
main(int argc, char** argv)
{
	BApplication app("application/x-vnd.example-translate");

	if (argc < 3) {
		printf("Usage: translate <input> <output>\n");
		return 1;
	}

	BFile inputFile(argv[1], B_READ_ONLY);
	if (inputFile.InitCheck() != B_OK) {
		printf("Failed to open input file\n");
		return 1;
	}

	BFile outputFile(argv[2], B_WRITE_ONLY | B_CREATE_FILE | B_ERASE_FILE);
	if (outputFile.InitCheck() != B_OK) {
		printf("Failed to open output file\n");
		return 1;
	}

	BTranslatorRoster* roster = BTranslatorRoster::Default();

	BBitmapStream outputStream;

	status_t result = roster->Translate(&inputFile, NULL, NULL,
		&outputStream, B_TRANSLATOR_BITMAP);

	if (result != B_OK) {
		printf("Translation failed: %s\n", strerror(result));
		return 1;
	}

	BBitmap* bitmap = NULL;
	outputStream.DetachBitmap(&bitmap);

	if (bitmap != NULL) {
		printf("Translation succeeded: %ldx%ld\n",
			(int32)bitmap->Bounds().Width() + 1,
			(int32)bitmap->Bounds().Height() + 1);
		delete bitmap;
	}

	return 0;
}
