#include "BitmapView.h"

#include <GroupLayout.h>

BitmapView::BitmapView()
	:
	BView("bitmap view", B_WILL_DRAW),
	fBitmap(NULL)
{
	SetExplicitMinSize(BSize(300, 200));

	BRect bitmapRect(0, 0, 63, 63);
	fBitmap = new BBitmap(bitmapRect, B_RGB32);

	uint8* bits = (uint8*)fBitmap->Bits();
	int32 bpr = fBitmap->BytesPerRow();

	for (int y = 0; y <= 63; y++) {
		for (int x = 0; x <= 63; x++) {
			uint8* pixel = bits + y * bpr + x * 4;
			pixel[0] = (uint8)(x * 4);
			pixel[1] = (uint8)(y * 4);
			pixel[2] = 128;
			pixel[3] = 255;
		}
	}
}

BitmapView::~BitmapView()
{
	delete fBitmap;
}

void
BitmapView::Draw(BRect updateRect)
{
	if (fBitmap == NULL)
		return;

	BRect srcRect = fBitmap->Bounds();
	BRect dstRect = Bounds();

	DrawBitmap(fBitmap, srcRect, dstRect);
}
