{
}


void
TextMetricsView::Draw(BRect updateRect)
{
	BFont font;
	GetFont(&font);

	font_height metrics;
	font.GetHeight(&metrics);

	const char* text = "Hello from Haiku!";

	float x = 20.0f;
	float y = 40.0f + metrics.ascent;

	SetHighColor(0, 0, 0);
	MovePenTo(x, y);
	DrawString(text);

	float baseline = y;
	float descent = baseline + metrics.descent;
	float ascent = baseline - metrics.ascent;

	SetHighColor(200, 0, 0);
	StrokeLine(BPoint(x, baseline), BPoint(x + StringWidth(text), baseline));

	SetHighColor(0, 0, 200);
	StrokeLine(BPoint(x, ascent), BPoint(x + StringWidth(text), ascent));

	SetHighColor(0, 160, 0);
	StrokeLine(BPoint(x, descent), BPoint(x + StringWidth(text), descent));
}
