### CanvasView.cpp
```cpp
#include "CanvasView.h"

#include <Bitmap.h>
#include <View.h>

CanvasView::CanvasView()
	:
	BView(NULL, B_FOLLOW_ALL, B_WILL_DRAW),
	fBitmap(NULL)
{
}

CanvasView::~CanvasView()
{
	delete fBitmap;
}

void
CanvasView::AttachedToWindow()
{
	BRect bitmapRect(0, 0, 79, 79);
	fBitmap = new BBitmap(bitmapRect, B_RGB32, true);

	BView* offscreen = new BView(bitmapRect, NULL, B_FOLLOW_NONE, 0);
	fBitmap->AddChild(offscreen);
	fBitmap->Lock();

	offscreen->SetHighColor(180, 80, 80);
	offscreen->FillRect(bitmapRect);
	offscreen->SetHighColor(255, 255, 255);
	offscreen->FillEllipse(BRect(15, 15, 65, 65));
	offscreen->Sync();

	fBitmap->Unlock();
}

void
CanvasView::Draw(BRect updateRect)
{
	if (fBitmap == NULL)
		return;

	MovePenTo(BPoint(20, 20));
	DrawBitmap(fBitmap, PenLocation());

	MovePenTo(BPoint(140, 60));
	DrawBitmap(fBitmap, PenLocation());

	MovePenTo(BPoint(260, 30));
	DrawBitmap(fBitmap, PenLocation());
}
