#include <Window.h>

MouseView::MouseView()
	:
	BView("mouseview", B_WILL_DRAW | B_FULL_UPDATE_ON_RESIZE),
	fLastPosition(0, 0),
	fButtonDown(false),
	fTransit(B_OUTSIDE_VIEW)
{
	SetViewUIColor(B_PANEL_BACKGROUND_COLOR);
}


MouseView::~MouseView()
{
}


void
MouseView::MouseDown(BPoint where)
{
	fButtonDown = true;
	fLastPosition = where;
	SetMouseEventMask(B_POINTER_EVENTS, B_LOCK_WINDOW_FOCUS);
	Invalidate();
}


void
MouseView::MouseUp(BPoint where)
{
	fButtonDown = false;
	fLastPosition = where;
	Invalidate();
}


void
MouseView::MouseMoved(BPoint where, uint32 transit, const BMessage* message)
{
	fLastPosition = where;
	fTransit = transit;
	Invalidate();
}


void
MouseView::Draw(BRect updateRect)
{
	BString status;
	status << "Position: (" << fLastPosition.x << ", " << fLastPosition.y << ")";

	BString buttonStatus = fButtonDown ? "Button: DOWN" : "Button: UP";

	BString transitStatus;
	switch (fTransit) {
		case B_ENTERED_VIEW:
			transitStatus = "Transit: ENTERED";
			break;
		case B_INSIDE_VIEW:
			transitStatus = "Transit: INSIDE";
			break;
		case B_EXITED_VIEW:
			transitStatus = "Transit: EXITED";
			break;
		case B_OUTSIDE_VIEW:
			transitStatus = "Transit: OUTSIDE";
			break;
	}

	MovePenTo(20, 40);
	DrawString(status);
	MovePenTo(20, 70);
	DrawString(buttonStatus);
	MovePenTo(20, 100);
	DrawString(transitStatus);
}
