	MSG_SCROLL_LEFT		= 'slft',
	MSG_SCROLL_RIGHT	= 'srgt',
	MSG_SCROLL_TOP		= 'stop',
	MSG_RESET			= 'rset'
};

MainWindow::MainWindow()
	:
	BWindow(BRect(100, 100, 700, 500), "ScrollTo / ScrollBy",
		B_TITLED_WINDOW, B_QUIT_ON_WINDOW_CLOSE | B_AUTO_UPDATE_SIZE_LIMITS)
{
	ScrollView* scrollView = new ScrollView();

	BButton* leftButton = new BButton("Left", new BMessage(MSG_SCROLL_LEFT));
	BButton* rightButton = new BButton("Right", new BMessage(MSG_SCROLL_RIGHT));
	BButton* topButton = new BButton("Top", new BMessage(MSG_SCROLL_TOP));
	BButton* resetButton = new BButton("Reset", new BMessage(MSG_RESET));

	BLayoutBuilder::Group<>(this, B_VERTICAL)
		.Add(scrollView)
		.AddGroup(B_HORIZONTAL)
			.Add(leftButton)
			.Add(rightButton)
			.Add(topButton)
			.Add(resetButton)
		.End()
		.SetInsets(B_USE_DEFAULT_SPACING);

	fScrollView = scrollView;
}

void
MainWindow::MessageReceived(BMessage* message)
{
	switch (message->what) {
		case MSG_SCROLL_LEFT:
			fScrollView->ScrollBy(-40, 0);
			break;
		case MSG_SCROLL_RIGHT:
			fScrollView->ScrollBy(40, 0);
			break;
		case MSG_SCROLL_TOP:
			fScrollView->ScrollBy(0, -40);
			break;
		case MSG_RESET:
			fScrollView->ScrollTo(0, 0);
			break;
		default:
			BWindow::MessageReceived(message);
	}
}
