### Benaphore.cpp
```cpp
#include "Benaphore.h"

#include <atomic>

Benaphore::Benaphore(const char* name)
	:
	fAtomicCount(0),
	fSemaphore(create_sem(0, name))
{
}


Benaphore::~Benaphore()
{
	if (fSemaphore >= 0)
		delete_sem(fSemaphore);
}


status_t
Benaphore::Lock()
{
	if (atomic_add(&fAtomicCount, 1) > 0)
		return acquire_sem(fSemaphore);

	return B_OK;
}


void
Benaphore::Unlock()
{
	if (atomic_add(&fAtomicCount, -1) > 1)
		release_sem(fSemaphore);
}


bool
Benaphore::IsValid() const
{
	return fSemaphore >= 0;
}
```

### main.cpp
```cpp
#include "Benaphore.h"

#include <Application.h>
#include <OS.h>
#include <stdio.h>

static Benaphore gBenaphore("shared_benaphore");
static int32 gSharedCounter = 0;


static status_t
WorkerThread(void* data)
{
	int32 id = (int32)(addr_t)data;

	for (int i = 0; i < 5; i++) {
		gBenaphore.Lock();

		gSharedCounter++;
		printf("Thread %" B_PRId32 " incremented counter to %" B_PRId32 "\n",
			id, gSharedCounter);

		gBenaphore.Unlock();

		snooze(1000);
	}

	return B_OK;
}


int
main()
{
	if (!gBenaphore.IsValid()) {
		fprintf(stderr, "Failed to create benaphore\n");
		return 1;
	}

	const int32 kThreadCount = 4;
	thread_id threads[kThreadCount];

	for (int32 i = 0; i < kThreadCount; i++) {
		threads[i] = spawn_thread(WorkerThread, "worker", B_NORMAL_PRIORITY,
			(void*)(addr_t)i);
		resume_thread(threads[i]);
	}

	for (int32 i = 0; i < kThreadCount; i++)
		wait_for_thread(threads[i], NULL);

	printf("Final counter value: %" B_PRId32 "\n", gSharedCounter);

	return 0;
}
