void
ContentView::MouseDown(BPoint where)
{
	uint32 buttons;
	GetMouse(&where, &buttons);

	if (buttons & B_SECONDARY_MOUSE_BUTTON) {
		BPopUpMenu* menu = new BPopUpMenu("context", false, false);

		menu->AddItem(new BMenuItem("Action One",
			new BMessage('ACT1')));
		menu->AddItem(new BMenuItem("Action Two",
			new BMessage('ACT2')));
		menu->AddSeparatorItem();
		menu->AddItem(new BMenuItem("Close",
			new BMessage(B_QUIT_REQUESTED)));

		BPoint screenWhere = ConvertToScreen(where);
		BMenuItem* selected = menu->Go(screenWhere);

		if (selected != NULL) {
			BMessage* msg = selected->Message();
			if (msg != NULL && msg->what == B_QUIT_REQUESTED)
				Window()->PostMessage(B_QUIT_REQUESTED);
		}

		delete menu;
	}
}
