#include <OS.h>
#include <stdio.h>

sem_id gSemaphore;

status_t
producer_thread(void* data)
{
	printf("Producer: doing work...\n");
	snooze(500000);
	printf("Producer: releasing semaphore\n");
	release_sem(gSemaphore);
	return B_OK;
}

status_t
consumer_thread(void* data)
{
	printf("Consumer: waiting for semaphore\n");
	acquire_sem(gSemaphore);
	printf("Consumer: acquired semaphore, proceeding\n");
	return B_OK;
}

int
main()
{
	gSemaphore = create_sem(0, "my_semaphore");
	if (gSemaphore < B_OK) {
		printf("Failed to create semaphore\n");
		return 1;
	}

	thread_id consumer = spawn_thread(consumer_thread, "consumer", B_NORMAL_PRIORITY, NULL);
	thread_id producer = spawn_thread(producer_thread, "producer", B_NORMAL_PRIORITY, NULL);

	resume_thread(consumer);
	resume_thread(producer);

	wait_for_thread(consumer, NULL);
	wait_for_thread(producer, NULL);

	delete_sem(gSemaphore);

	return 0;
}
