main()
{
	thread_id worker = spawn_thread(worker_thread, "worker", B_NORMAL_PRIORITY, NULL);
	resume_thread(worker);

	status_t exitValue;
	wait_for_thread(worker, &exitValue);
	printf("Worker exited with: %s\n", strerror(exitValue));

	thread_id task = spawn_thread(long_task, "long_task", B_NORMAL_PRIORITY, NULL);
	resume_thread(task);

	snooze(200000);
	status_t result = kill_thread(task);
	printf("kill_thread result: %s\n", strerror(result));

	return 0;
}
