#include <TLS.h>
#include <OS.h>
#include <stdio.h>
#include <stdlib.h>

static int32 sTLSKey = -1;

static status_t
thread_func(void* data)
{
	int* value = (int*)malloc(sizeof(int));
	*value = (int)(addr_t)data;

	tls_set(sTLSKey, value);

	int* stored = (int*)tls_get(sTLSKey);
	printf("Thread %d: TLS value = %d\n", find_thread(NULL), *stored);

	free(value);
	return B_OK;
}

int
main()
{
	sTLSKey = tls_allocate();
	if (sTLSKey < 0) {
		fprintf(stderr, "tls_allocate failed\n");
		return 1;
	}

	thread_id t1 = spawn_thread(thread_func, "worker1", B_NORMAL_PRIORITY, (void*)42);
	thread_id t2 = spawn_thread(thread_func, "worker2", B_NORMAL_PRIORITY, (void*)99);

	resume_thread(t1);
	resume_thread(t2);

	wait_for_thread(t1, NULL);
	wait_for_thread(t2, NULL);

	return 0;
}
